def check(root, argv, runner='command', timeout=1800):
    """Any owner can request feedback directly; Gradle uses the existing mutex."""
    if not argv:
        raise ProtocolError('check command/tasks required')
    if runner == 'gradle' and sys.platform == 'win32':
        directory = root / '.vibe/requests'
        path = directory / f'lean-check-{uuid.uuid4()}.json'
        # Machine-generated transport, not an agent-authored coverage request.
        atomic_write_json(path, {'tasks': argv, 'kind': 'integration',
            'coveredObligations': [], 'timeoutSeconds': timeout}, refuse_existing=True)
        shell = shutil.which('pwsh') or shutil.which('powershell')
        if not shell:
            raise ProtocolError('PowerShell required for serialized Windows Gradle runner')
        code, out, err, status = execute_process([shell, '-NoProfile', '-File',
            str(Path(__file__).with_name('run-gradle.ps1')), '-ProjectRoot', str(root),
            '-RequestPath', str(path)], cwd=root, timeout=timeout + 650)
        return code, (out + err).decode('utf-8', errors='replace')[-2000:]
    if runner == 'gradle':
        argv = [str(root / 'gradlew'), '--no-parallel', '--max-workers=1', *argv]
    with file_lock(root / '.vibe/jobs/command-runner.lock', timeout=600):
        path, receipt = load_script('run-check').run_check(root, argv, [], 'integration', timeout, serialized_gradle=runner == 'gradle')
    return (0 if receipt['exitCode'] == 0 and receipt['executionStatus'] == 'completed' else 1), str(path)


def request_audit(root, previous=None):
    value = state(root)
    app_root, app = spec(root, value['appSpec'])
    app_fp = compute_app_spec_fingerprint(app_root)
    if not fingerprint_equal(app_fp, value['appSpecFingerprint']):
        raise ProtocolError('AppSpec changed: adopt-spec with saved authorization first')
    prior = None
    if previous:
        previous_path = local(root, previous)
        old = read_json(previous_path)
        if old.get('mode') != 'lean' or not fingerprint_equal(old.get('appSpecFingerprint'), app_fp):
            raise ProtocolError('delta audit requires unchanged AppSpec and a lean predecessor')
        launch = read_json(previous_path.with_name('launch.json'))
        audit = read_json(previous_path.with_name('audit.json'))
        if launch.get('executionStatus') != 'completed' or launch.get('exitCode') != 0 or not launch.get('threadId'):
            raise ProtocolError('previous audit did not finish independently')
        if audit.get('requestSha256') != sha256_bytes(previous_path.read_bytes()):
            raise ProtocolError('previous audit binding mismatch')
        prior = {'request': previous_path.relative_to(root).as_posix(),
            'requestSha256': sha256_bytes(previous_path.read_bytes()), 'threadId': launch['threadId'],
            'auditSha256': sha256_bytes(previous_path.with_name('audit.json').read_bytes())}
    request_id = f'AUDIT-REQUEST-{uuid.uuid4()}'
    path = root / '.vibe/audits' / request_id / 'request.json'
    request = {'schemaVersion': '1.0', 'mode': 'lean', 'requestId': request_id,
        'createdAt': utc_now(), 'appSpec': value['appSpec'], 'appSpecFingerprint': app_fp,
        'workspaceFingerprint': compute_workspace_fingerprint(root),
        'implementationContextAvailable': False, 'previousAudit': prior,
        'unavailablePairs': [r for r in host_availability(app)['surfaces'] if not r['available']]}
    atomic_write_json(path, request, refuse_existing=True)
    with file_lock(root / '.vibe/work.json.lock'):
        current = state(root)
        current['auditRequest'] = path.relative_to(root).as_posix()
        current['updatedAt'] = utc_now()
        atomic_write_json(root / '.vibe/work.json', current)
    return path


