private final class IosApplicationHost: ObservableObject {
    enum LifecycleState {
        case created
        case started
        case resumed
        case stopped
    }

    let graph: IosProductionAppGraph
    let platformServices: NativePlatformServices
    private var lifecycleState = LifecycleState.created

    init() {
#if DEBUG
        let isDebug = true
#else
        let isDebug = false
#endif
        let archiveImports = IosArchiveImportCoordinator()
        platformServices = NativePlatformServiceFactory.make(archiveImports: archiveImports)
        graph = IosProductionAppGraph(
            isDebug: isDebug,
            crashReportingBridge: platformServices.crashReporting,
            archiveImports: archiveImports
        )
    }

    deinit {
        graph.close()
    }

    func timeZoneDidChange() {
        graph.onTimeZoneChanged()
    }

    func transition(to scenePhase: ScenePhase) {
        switch scenePhase {
        case .active:
            startIfNeeded()
            guard lifecycleState == .started else { return }
            graph.onResume()
            lifecycleState = .resumed
            platformServices.didBecomeActive()
        case .inactive:
            startIfNeeded()
            pauseIfNeeded()
        case .background:
            pauseIfNeeded()
            guard lifecycleState == .started else { return }
            graph.onStop()
            lifecycleState = .stopped
        @unknown default:
            break
        }
    }

    private func startIfNeeded() {
        guard lifecycleState == .created || lifecycleState == .stopped else { return }
        graph.onStart()
        lifecycleState = .started
    }

    private func pauseIfNeeded() {
        guard lifecycleState == .resumed else { return }
        graph.onPause()
        lifecycleState = .started
    }
}

